quests[44202] = { id = 44202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Cause", objectives = "{name}, I hope you don't mind me dropping by unexpectedly. I was in the area on business.\n\nMy people procured what look to be some rather nice armaments for the cause. I'm sure that you know best how to distribute them.\n\nDo not doubt that our continued cooperation, even if it is a bit cloak and dagger, is making a huge difference in the war against the Burning Legion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44203] = { id = 44203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Cause", objectives = "Shadowblade {name}, always a pleasure. I was in the area on Alliance business and decided to drop in. It looks like our operations are faring well.\n\nMy people procured what look to be some rather nice armaments for the cause. I'm sure that you know best how to distribute them.\n\nThough we must continue to cooperate through back channels and behind closed doors, know that for the duration of the war against the Burning Legion, you can count on my support and that of SI:7.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44204] = { id = 44204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seal their Fates", description = "Ever feel like luck just isn't on your side?  Well maybe I can help you with that.  \n\nThere are some interesting items I've come across in my travels which can be used to swing the dice in your favor, or at least give you another shot at it.  It takes some time, and supplies are hard to come by, but I can get you one of them... for a price?", completion = "The order has been sent. Once my people have procured the item, it will be here for you to collect.\n\nGood... luck.", objectives = "Place a work order for a Seal of Broken Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44205] = { id = 44205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shape Your Fate", description = "The whims of the spirits can be guided, I have seen it.\n\nThere were whispers of an item, a way to change the path of destiny.  I heard dem, and I went looking.  For many years I listened to those whispers on the wind until one day they showed me the way.  This is what I offer you.  It will take some time, and some valuable resources, but I can perform the ritual to allow you to control this power.\n\nWell?  Are you ready?", progress = "Place a work order  for a Seal of Broken Fate.", completion = "The ritual has begun. This will take some time. Return later." }
quests[44206] = { id = 44206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ascended", description = "These shaman have spent their lives dedicated to the path of Air, Water or Fire.  On your request, we will beseech the elements to Ascend them, becoming a powerful, if short lived, force to deploy in this war against the Legion.\n\nThe ritual of ascension is not to be requested lightly.", completion = "The ritual has begun, they will Rise.  Return here when the ritual is complete.", objectives = "Place a request to recruit Ascendants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44207] = { id = 44207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal Full of Shiny Things", description = "When I heard the Hall of the Guardian was open again, I said to myself \"Minuette, this is your chance!\" I rushed over here thinking I'd be hurled into the front lines.  Imagine it, me, little old me, assaulting Demons with missiles, blinking away from Fel Meteors.  That would be brilliant!\n\nInstead, they send me over here and say \"Hey, open up some portals so we can throw things through, would you?\" At least I get to charge something for it.", completion = "All those years of study are really paying off...\n\nOnce they've sent the shipment through, it will be waiting here for you.", objectives = "Place a work order for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44208] = { id = 44208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate and Time", description = "For years we wondered, we conjectured, that it was possible to control the twisting, slipping, streaming threads of fate and destiny.  These books tell of powerful mages who embraced the manipulation of time.  No no, not like Time Warp, they would laugh at us, think us silly amateurs.  No, they were true Chronomancers.\n\nThe only spell we've been able to determine is a conjuration.  It calls forth what they termed  a \"Seal of Fate\".  This allowed them to repeat their actions.  Let us try it out shall we?", completion = "The spell has begun. Return to me when it is complete. Fate is in the hands of time now.", objectives = "Place a work order for a Seal of Broken Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44209] = { id = 44209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of Dalaran", description = "In times of great need, the mages of Dalaran can focus their power into one pure, destructive form.  This is such a time.\n\nOn request, these mages will channel that power into a focusing crystal, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", progress = "Channel the power of Dalaran into the focusing crystal, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts.  It will be some time before we can do that again." }
quests[44210] = { id = 44210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of Dalaran pt2", description = "Yes, now once the crystal has been empowered, collect it here, and use it to unleash the power of our mages on a world quest.", objectives = "Collect the Focusing Crystal and use it to complete a world quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44211] = { id = 44211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseen Armaments", description = "If we gonna win dis war, we need to get these Champions of ours better equipment.  \n\nIt won't be cheap, or easy, but I can get dem for you.", completion = "The order has been issued. Once the shipment arrives it will be here for you to collect.", objectives = "Place a work order for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44212] = { id = 44212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseen Fate", description = "Our path is a winding, twisting road full of peril.  Yet did you know it can be walked many times?  There is an item of great power available to us.  It allows us another opportunity, a second chance.\n\nDo you wish to acquire one?", completion = "Word has been sent. The Seal will arrive soon.", objectives = "Place a work order for a Seal of Broken Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44213] = { id = 44213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Will Be Prepared!", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Illidari are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", completion = "Our glaives are yours, {name}.", objectives = "Accept a gift from the Illidari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44214] = { id = 44214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One More Thing...", description = "Well done, Slayer. You are truly now the leader of the Illidari. But there's one more thing.\n\nMeet me down at the forge.", completion = "Excellent. You're going to like this.", objectives = "Head down to the chamber of the Cursed Forge of the Nathrezim on the lower level of the Fel Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44215] = { id = 44215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One More Thing...", description = "Firstly, allow me to congratulate you. I know of no one more deserving of the title of Shadowblade. But there's one more thing.\n\nMeet me over near the forge.", completion = "I think you will appreciate this. I must admit to a certain level of envy.", objectives = "Meet Lord Ravenholdt in the Uncrowned Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44217] = { id = 44217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Fit For A Deathlord", description = "{name} is strong! {name} is great leader!\n\nEbon Blade want to give you full set of armor to help with the little demon killing. Get stronger, make demons more dead!", completion = "We is with you, {name}!", objectives = "Accept a gift from the Knights of the Ebon Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44218] = { id = 44218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Armaments", description = "This war against the Legion won't be won easily.  We will need armaments and equipment for our Champions.  \n\nGive the order sir, I'll get the word out and have a shipment brought in.", completion = "Aye, sir, the men have their orders.  Once the shipment arrives it will be here for you to collect.", objectives = "Place a work order for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44219] = { id = 44219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate's Blessing", description = "The Light's blessing is powerful. We use it to mend, to defeat our enemies... we even use it to resurrect our allies. Did you know it can also be used to alter your destiny?  \n\nThe Silver Hand is able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", completion = "Word has been sent. The Seal will arrive soon.", objectives = "Place a work order for a Seal of Broken Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44220] = { id = 44220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of the Order", description = "In times of great need, the Order can rally its mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, we will channel our power into a Libram, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", progress = "Send out the call to bring together the Vanguard, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
quests[44221] = { id = 44221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Armaments", description = "A warrior lives and dies by his weapons and armor.  For a price, we can provide you with a shipment for armaments to equip your Champions with.\n\nDo we have a deal?", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect.", objectives = "Place a workorder for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44222] = { id = 44222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Val'kyr", description = "In times of great need, the Val'kyr can rally its mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, these we will channel our power into a Horn, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", progress = "Rise the power of the Val'kyr, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
quests[44223] = { id = 44223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Armaments", description = "We will need armaments and equipment for our Champions.", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect.", objectives = "Place a workorder for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44224] = { id = 44224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleashing our Wrath", description = "In times of great need, we can rally our  mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, these we will channel our power into an item, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", completion = "Well done, though that certainly takes all of our efforts.", objectives = "Channel the power of the Hammer, then unleash it to complete a World Quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44226] = { id = 44226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate Favors Us", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", completion = "Word has been sent. The Seal will arrive soon.", objectives = "Place a work order for a Seal of Broken Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44227] = { id = 44227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleashing our Wrath", description = "In times of great need, we can rally our mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, these we will begin the ritual to enslave a powerful Infernal in a Demonic Phylactery, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", progress = "Begin the ritual to enslave the infernal, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
quests[44228] = { id = 44228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Armaments", description = "See Lurr?  He big and strong, but not so smart, not like Murr.  Murr can make Lurr build good things for you, things for your Champions to wear and be smashier.  \n\nFirst, you give Murr something?", completion = "Murr will make Lurr smash fast!  When he done smashing, we put it in box.  Box here for you later.", objectives = "Place a work order for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44229] = { id = 44229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Armaments", description = "We will need armaments and equipment for our Champions.", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect.", objectives = "Place a work order for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44230] = { id = 44230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fates Bless Us", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", completion = "Word has been sent. The Seal will arrive soon.", objectives = "Place a work order for a Seal of Broken Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44231] = { id = 44231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Armaments", description = "People today see a dead body and they just think its a smelly pile of goo, not me I tell ya. I see it as a little present holding wonderful secrets.  \n\nFor a price, Ill share those secrets with you too.", completion = "The order has been placed.  Once the shipment arrives it will be here for you to collect.", objectives = "Place a workorder for Champion armaments and equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44232] = { id = 44232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grove Provides", description = "{name}, your wisdom and leadership inspires awe in all of us!\n\nThe Dreamweavers are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", completion = "We are with you, {name}.", objectives = "Accept a gift from the Dreamweavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44233] = { id = 44233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk This Way", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Unseen Path is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", completion = "Yours is the path we will follow, {name}.", objectives = "Accept a gift from the Unseen Path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44234] = { id = 44234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleashing our Wrath", description = "In times of great need, we can rally our mightiest forces into one pure, destructive form.  This is such a time.\n\nOn request, these we will channel our power into an item, which we will impart to you.  Use it to unleash that power, completing a quest of great value.", progress = "Channel the power of the Frost Wyrm, then unleash it to complete a World Quest.", completion = "Well done, though that certainly takes all of our efforts." }
quests[44235] = { id = 44235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Fate", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", progress = "Place a work order for a Seal of Broken Fate.", completion = "Word has been sent. The Seal will arrive soon." }
