quests[44238] = { id = 44238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditations on Fate", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", completion = "Word has been sent. The Seal will arrive soon.", objectives = "Place a work order for a Seal of Broken Fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
