quests[44240] = { id = 44240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orange is the New Purple", description = "{name}, your intelligence and leadership inspires awe in all of us!\n\nTirisgarde is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", completion = "Our hearts and minds are with you, {name}.", objectives = "Accept a gift from the magi of Tirisgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44241] = { id = 44241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thassarian", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44242] = { id = 44242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nazgrim", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44243] = { id = 44243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thoras Trollbane", objectives = "These Knights of the Ebon Blade are a powerful order, Deathlord.\n\nThat you command such respect amongst their ranks speaks to your strength and leadership.\n\nDuring my life, I always fought to preserve my kingdom and people. But for my failure as a father, their blood now stains my hands.\n\nSo, I will wash the failure from my hands with the blood of demons. The time has come for me to return to the fray. My sword is yours to command.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44244] = { id = 44244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Koltira Deathweaver", objectives = "Words cannot fully express my gratitude for rescuing me, {name}. In truth, I always knew that the Ebon Blade would not forsake me.\n\nI do not wish to elaborate on my years in captivity. That time has passed and we are now presented with an imminent danger in the Burning Legion.\n\nMy blade is yours, Deathlord. My life and my allegiance are yours to command.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44245] = { id = 44245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: High Inquisitor Whitemane", objectives = "There is no greater hatred and scorn in this world than that which exists in my heart.\n\nThe Burning Legion will pay for all that they have taken from me.\n\nThe day of my judgment awaits, but theirs is at hand and I will be the executioner's blade. I will not rest until every demon lays dead, their corpses paving the very ground I walk!\n\nCommand me to the front, Deathlord and I will rain terror upon the armies of the Burning Legion!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44246] = { id = 44246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rottgut", objectives = "<Rottgut motions in your direction, gurgling and belching the words from its gaping mouth.>\n\nRottgut!!\n\nROTT. GUTT. ROTT! RottgutRottgutRottgut!!!\n\nGUT? ROTTGUTT, GUT. ROTT... GUT!\n\nRottgut??", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44247] = { id = 44247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Amal'thazad", objectives = "Deathlord, I have been your humble tutor in the dark arts for some years now. From your birth at the hands of the Lich King, to your ascension as leader of our order, I have taken pride in watching you grow in power and undeath.\n\nI believe the time has passed in which my services as a teacher are necessary. Perhaps I would be of more use to you on the battlefield?\n\nThe time has come for me to warm these frozen bones of mine in the blood my enemies. Please, allow me to be of service on the battlefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44248] = { id = 44248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Darion Mograine", objectives = "The Four Horsemen of the Ebon Blade are gathered together, but our work has only just begun.\n\nThe Burning Legion has come to our world hungering for destruction, but we will feed them their own demise. Apocalypse awaits the demon invaders and we shall bring it to them!\n\nDeathlord, you have triumphed where no others could have succeeded. I shall lead the Four Horsemen like my father before me, and so long as I lead them our loyalty is yours!\n\nThe return of the Four Horsemen is at hand!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
