quests[44254] = { id = 44254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazing Into Oblivion", description = "{name}, your wisdom and leadership inspires awe in all of us!\n\nThe Council of the Black Harvest is prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", completion = "The Council admires your power, {name}.", objectives = "Accept a gift from the Council of the Black Harvest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44255] = { id = 44255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Axe and You Shall Receive", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Valarjar are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", completion = "The might of the Valarjar stands with you, {name}.", objectives = "Accept a gift from the Valarjar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44257] = { id = 44257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Falling Star", description = "<Khadgar ponders the information that you brought to him.>\n\nYou say that it cut a swath through the Felstorm and was emanating power enough that your scout could feel it coursing through their body?\n\nSomething that powerful could prove to be a potent weapon against the Burning Legion!\n\nI will inform the other order leaders of your discovery while you investigate the matter further! A gryphon awaits your command at Krasus' Landing! Light guide you.", progress = "Show me what you've found.", completion = "Most curious indeed! This is no object of the Legion's making. Let me have a closer look.", objectives = "Find the Mysterious Lightbound Object.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44258] = { id = 44258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Violet Hold: Into the Violet Hold", description = "The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.", progress = "How are you finding the Violet Hold?", completion = "Were you able to overcome Violet Hold?", objectives = "Defeat the leader of the Assault on Violet Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44259] = { id = 44259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Violet Hold: Into the Violet Hold", description = "The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.", progress = "How are you finding the Violet Hold?", completion = "Were you able to overcome Violet Hold?", objectives = "Defeat the leader of the Assault on Violet Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44260] = { id = 44260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Wardens: Into the Vault of the Wardens", description = "It's worse than we thought within the Vault of the Wardens. The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there.\n\nEnter the Vault of the Wardens and cleanse the place of evil.", progress = "How are you finding the Vault of the Wardens?", completion = "Were you able to overcome Vault of the Wardens?", objectives = "Defeat Cordana Felsong in Vault of the Wardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44261] = { id = 44261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Wardens: Into the Vault of the Wardens", description = "It's worse than we thought within the Vault of the Wardens. The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there.\n\nEnter the Vault of the Wardens and cleanse the place of evil.", progress = "How are you finding the Vault of the Wardens?", completion = "Were you able to overcome Vault of the Wardens?", objectives = "Defeat Cordana Felsong in Vault of the Wardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44262] = { id = 44262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcway: Into the Arcway", description = "The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground.\n\nEnter The Arcway and clear out any, and all enemies.", objectives = "Defeat Advisor Vandros in The Arcway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44263] = { id = 44263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcway: Into the Arcway", description = "The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground.\n\nEnter The Arcway and clear out any, and all enemies.", progress = "How are you finding the The Arcway?", completion = "Were you able to overcome The Arcway?", objectives = "Defeat Advisor Vandros in The Arcway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44264] = { id = 44264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Into Neltharion's Lair", description = "Our scouts found that not only have the drogbar obtained a Titan relic, but also they've amassed an army large enough to threaten the overworld.\n\nDelve underground and stop the Underking before he can unleash the might of his drogbar army.", progress = "How are you finding the challenges within the Neltharion's Lair?", completion = "Were you able to overcome Neltharion's Lair?", objectives = "Defeat Dargrul in Neltharion's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44265] = { id = 44265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Into Neltharion's Lair", description = "Our scouts found that not only have the drogbar obtained a Titan relic, but also they've amassed an army large enough to threaten the overworld.\n\nDelve underground and stop the Underking before he can unleash the might of his drogbar army.", progress = "How are you finding the challenges within the Neltharion's Lair?", completion = "Were you able to overcome Neltharion's Lair?", objectives = "Defeat Dargrul in Neltharion's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44266] = { id = 44266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls: Into the Maw of Souls", description = "Our scouts report that the vrykul damned are forced to sail aboard the Naglfar, a ship built of death.\n\nTravel to the Maw of Souls and confront Helya, before she collects any more poor, unfortunate souls.", progress = "How are you finding the challenges within the Maw of Souls?", completion = "Were you able to overcome Maw of Souls?", objectives = "Defeat Helya in Maw of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
