quests[44270] = { id = 44270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: Into the Eye of Azshara", description = "Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles.\n\nTravel to the Eye of Azshara, and put a stop to the ritual.", progress = "How are you finding the Eye of Azshara?", completion = "Were you able to overcome Eye of Azshara", objectives = "Defeat the Wrath of Azshara in Eye of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44271] = { id = 44271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: Into the Eye of Azshara", description = "Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles.\n\nTravel to the Eye of Azshara, and put a stop to the ritual.", progress = "How are you finding the Eye of Azshara?", completion = "Were you able to overcome Eye of Azshara", objectives = "Defeat the Wrath of Azshara in Eye of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44272] = { id = 44272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: Into Darkheart Thicket", description = "Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. \n\nNot only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.", progress = "How are you finding the Darkheart Thicket?", completion = "Were you able to overcome Darkheart Thicket?", objectives = "Defeat the Shade of Xavius in Darkheart Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44273] = { id = 44273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: Into Darkheart Thicket", description = "Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. \n\nNot only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.", progress = "How are you finding the Darkheart Thicket?", completion = "Were you able to overcome Darkheart Thicket?", objectives = "Defeat the Shade of Xavius in Darkheart Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44274] = { id = 44274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court of Stars: Into the Court of Stars", description = "The weather is perfect for a party, isn't it?\n\nTravel to the Court of Stars, where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.", objectives = "Defeat Advisor Melandrus in Court of Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44275] = { id = 44275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court of Stars: Into the Court of Stars", description = "The weather is perfect for a party, isn't it?\n\nTravel to the Court of Stars, where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.", progress = "How are you finding the Court of Stars?", completion = "Were you able to overcome the challenge?", objectives = "Defeat Advisor Melandrus in Court of Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44276] = { id = 44276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold: The Lord of Black Rook Hold", description = "While investigating the remains of Black Rook Hold, our Champions were ambushed!  The Lord of the Rook appears to have allied himself with the Legion.\n\nWe need your assistance to defeat his growing army, and bring him down.", progress = "Have you been to Black Rook Hold?", completion = "Were you able to defeat Lord Ravencrest?", objectives = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44277] = { id = 44277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold: The Lord of Black Rook Hold", description = "While investigating the remains of Black Rook Hold, our Champions were ambushed!  The Lord of the Rook appears to have allied himself with the Legion.\n\nWe need your assistance to defeat his growing army, and bring him down.", progress = "Have you been to Black Rook Hold?", completion = "Were you able to defeat Lord Ravencrest?", objectives = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44278] = { id = 44278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari Freedom", description = "<Arduen Soulblade is bleeding from several ghastly wounds. It appears he was left here to die.>\n\nWithin the prison are three of our... <cough>... comrades.\n\nWe were taken by surprise while scouting the area.\n\nI am not long for this world, {name}, but please... you can still save them.", completion = "We mourn together brother over the loss of Arduen, Cassiel, and Sirius. But, I owe you my life... again.\n\nThere is one thing I learned during my time in the prisons: the demons within Black Rook Hold must die.", objectives = "Free Sirius Ebonwing, Cassiel Nightthorn, and Asha Ravensong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44279] = { id = 44279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 0xx - Bloodhunt Highland - S (RKS)" }
quests[44280] = { id = 44280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 0x2 - Bloodhunt Highland - S (RKS)" }
quests[44281] = { id = 44281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Be Prepared", description = "Our allies have made the journey to Orgrimmar to support our war efforts.\n\nStop and visit with them, {name}. Their assistance will secure our victory today.", progress = "Blood and thunder, friend.", completion = "You look quite prepared for battle. Do not let the bloodlust overtake you out there.\n\nThe Warchief wishes to present you with this ring before you head to war. May you return with the heads of many demons.", objectives = "Visit Horde forces in Dranosh'ar Blockade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44282] = { id = 44282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: The Frozen Soul", description = "Ah, Deathlord. It is good to see you. I happen to have a fascinating task for you, should you be in the mood for adventure.\n\nI recently came across an obscure reference to an ancient amulet that was created by Queen Azshara herself! It is called the Frozen Soul Pendant and it offers tremendous power to those who channel the power of frost.\n\nI have reason to believe that it may be found somewhere within the Eye of Azshara.\n\nRetrieve the pendant for me, and it will prove most useful in my studies.", progress = "Have you retrieved the pendant?", completion = "So this is the legendary Frozen Soul Pendant! I sense a great power in this item...\n\nI will begin my study of it at once. You have my gratitude, Deathlord.", objectives = "Retrieve the Frozen Soul Pendant from the Wrath of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44283] = { id = 44283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", progress = "If only Cenarius were with us, we could confront Xavius at once.", completion = "Incredible... where did you find these? With these Essences, I will be able to open the way directly to the heart of the Nightmare. Let us make haste!", objectives = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Normal difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44284] = { id = 44284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", progress = "If only Cenarius were with us, we could confront Xavius at once.", completion = "Incredible... where did you find these? With these Essences, I will be able to open the way directly to the heart of the Nightmare. Let us make haste!", objectives = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44285] = { id = 44285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", progress = "If only Cenarius were with us, we could confront Xavius at once.", completion = "Incredible... where did you find these? With these Essences, I will be able to open the way directly to the heart of the Nightmare. Let us make haste!", objectives = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44286] = { id = 44286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Wardens: A Masterpiece of Flesh", description = "Ah, Deathlord! What a pleasant surprise! It is not often that you visit my workshop of blood and flesh.\n\nActually, I have something quite special to show you. I have been developing a new type of abomination that mixes the flesh of demons with that of humans.\n\nMy first prototype, Rottgut, is nearly complete! However I am still missing some of the more difficult-to-find body items.\n\nThe prisoners in the Vault of the Wardens should make fine donors for the parts I require.", progress = "Have you retrieved the parts?", completion = "Yes, these parts shall do nicely!\n\nNow go on and introduce yourself to Rottgut! I'm sure the two of you will get along... infamously!", objectives = "Retrieve the Beating Fel-Heart and Demonic Entrails from Vault of the Wardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44287] = { id = 44287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEADLY: Withered J'im" }
