quests[44336] = { id = 44336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: The Missing Vessel 4" }
quests[44337] = { id = 44337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goddess Watch Over You", description = "I may have found a \"key\" to unlock Light's Heart, {name}.\n\nI was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow.\n\nIf Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart.\n\nIt's a long shot, but we've got nothing left to lose.\n\nMeet me in Dalaran. I will ready the Tears of Elune for you.", completion = "If this works, then perhaps there is still hope for Turalyon and the Army of the Light.", objectives = "Meet Archmage Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44338] = { id = 44338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goddess Watch Over You", description = "I may have found a \"key\" to unlock Light's Heart, {name}.\n\nI was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow.\n\nIf Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart.\n\nNow it falls upon you to recover the Tears of Elune from Val'sharah.", completion = "If this works, then perhaps there is still hope for Turalyon and the Army of the Light.", objectives = "Recover the Tears of Elune from Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
