quests[44400] = { id = 44400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Violet Hold: Purple Pain", description = "Again! It happened again!\n\nSure, it's the Legion that staged the prison breakout this time, but I *told* them it was a bad idea to keep some of the most dangerous beings on Azeroth in a prison inside our city!\n\nWe can talk about relocating later, I suppose. Right now, we've got some... pacification to tend to.\n\nCan you help?", progress = "Oh, no. Don't tell me something ELSE has gone wrong?!", completion = "Whew. That's a SECOND invasion dealt with. Well done.\n\nNow, who do I talk to about getting this place shut down?", objectives = "Repel the Assault on Violet Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44401] = { id = 44401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weapon For Every Occasion", description = "Our ally, the Lich King, has offered to provide you with a lead on a final weapon should you desire to maximize our offensive options.\n\nLet me know how you would like to proceed.", completion = "Very well.", objectives = "Let Duke Lankral know if you'd like to pursue another artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44402] = { id = 44402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Chosen" }
