quests[44404] = { id = 44404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Chosen" }
quests[44405] = { id = 44405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 047 - Smuggler's Camp" }
quests[44406] = { id = 44406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggra's Guidance", description = "{class}t, have you met the shaman Aggra? Born of a shattered world, she learned the ways of the elements among the Mag'har orcs of Outland. On the eve of the Cataclysm she took it upon herself to complete Thrall's shamanistic training. Our younger initiates are fortunate to have her among us to guide them.\n\nIf you wish to seek out a second artifact, Aggra can assist you. She is training new recruits above us on the Storm's Eye Overlook.", completion = "I have been waiting for you, Farseer.", objectives = "Seek out Aggra at the Storm's Eye Overlook within the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44407] = { id = 44407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Legend", description = "You have not one but TWO powerful artifacts to use against the Legion. But can you imagine a world where you have three? Think of what you could do in such a world!\n\nShall we look at the possibilities?", completion = "That was probably the easiest decision you've had to make! Let's get started.", objectives = "Speak with Alonsus Faol to pursue a third artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44408] = { id = 44408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Chosen" }
quests[44409] = { id = 44409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disc Chosen" }
quests[44410] = { id = 44410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Chosen" }
quests[44411] = { id = 44411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Humming Crystal", description = "<You place the crystal to your ear and hear the disharmonious din of hundreds of voices speaking at once. Perhaps Khadgar might know more about this strange gem.>", completion = "Such a cacophony! I could hear it before you pulled it from your pack.\n\nWhat you've got there is a highborne memory crystal, somehow still intact. Created by ancient sorcery, they were used to store memories, stories, music, history, and whatnot.\n\nQuite rare! With a little... tinkering... I should be able to create something useful with it.", objectives = "Take the Strange Humming Crystal to Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44412] = { id = 44412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Everywhere", description = "Hold a moment, {name}. While I look into this orb of yours, why don't you look into something for me?\n\nI have long suspected an infiltration of Dalaran but after an embarrassing encounter with a local florist I've withheld my accusations until I'm absolutely certain.\n\nHave you noticed citizens among us that seem just too mundane? Almost inhumanly so? Spies, serving dark masters, watch and wait until our backs are turned. Root them out, but try and keep it quiet.", progress = "Have you disposed of our friends?", completion = "I appreciate your discretion, {name}.\n\nNow, look here! I have imparted all of my substantial worldly wisdom into this globe, in addition to my ruggedly handsome features. No doubt you will find my counsel invaluable in your travels.\n\nI could only get it to say a handful of phrases, however, so be VERY SPECIFIC in your questions.", objectives = "Defeat the hidden infiltrators in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44414] = { id = 44414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felspawns of Lothros", description = "These Felspawns are endless! I can't cut them down quickly enough to get to the dreadlord within the mausoleum.\n\nMaster Illidan, will you come with me so we can take down Lothros together?", progress = "A dreadlord poses little danger to you, eh?", completion = "We've done it! Without you, I fear I would have eventually succumbed to the onslaught.", objectives = "Defeat Lothros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44415] = { id = 44415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Red Axe", description = "Broxigar the Red is cornered on the bridge. I am not sure he would ever admit that he needs our help, but I feel it only proper to lend him our aid.\n\nIf you wish to assist our ally, I would be humbled to accompany you in this endeavor.", progress = "Our allies are strong, but our enemy is Legion!", completion = "A wise warrior welcomes all allies. You fight with the strength of an orc.", objectives = "Close the Unstable Portals and make your way to Broxigar the Red.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44416] = { id = 44416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter of Night", description = "A glorious battle indeed!\n\nIf I am correct, we can expect something a bit more deadly at any moment.\n\nThe Legion often uses fodder such as these to prepare the way for a more worthy foe.\n\nMy axe is sharp and ready.", progress = "Are you sure you are a night elf? You wage battle with the ferocity of an orc!", completion = "The spirits honor us with a day of glorious combat! You have my well-earned respect, Illidan Stormrage. I will gladly follow you into any battle.", objectives = "Defeat Malvingeroth", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44417] = { id = 44417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One More Legend", description = "Two is good, but three would be better. You should pursue another artifact to add to your armory.\n\nWhat say you?", completion = "That will definitely increase your power greatly.", objectives = "Speak with Odyn to pursue another artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44418] = { id = 44418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Chosen" }
quests[44419] = { id = 44419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms Chosen" }
quests[44420] = { id = 44420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prot Chosen" }
quests[44421] = { id = 44421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anomalous Anomalies", description = "Dalaran's move to this location was intended to be a temporary measure, but we may need to depart sooner than expected.\n\nBlinking a city across the world is no mean feat. The magnitude of energies involved can lead to... unexpected side effects.\n\nArcane anomalies are causing mischief throughout the city. Their presence could destabilize any attempt to blink again.\n\nWe don't have time to let them dissipate on their own, {name}. I have a device that will help speed things along.", completion = "Good work. There are still some stray anomalies floating about, but you've negated enough interference that we should no longer be prevented from relocating the city.\n\nNow we just need to determine our destination.", objectives = "Use Khadgar's crystal to neutralize anomalies in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44424] = { id = 44424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Paths, Three Weapons", description = "We've searched and found a lead upon another artifact that you might find helpful.\n\nHere, let me show you what I've found. If it interests you then simply let me know.", completion = "A wise choice.", objectives = "Choose a third artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44426] = { id = 44426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talking Pair Flavor Heard" }
