quests[44429] = { id = 44429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windwalker Chosen" }
quests[44431] = { id = 44431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Weapons of Old", description = "You've had great success against our foes, but you should be ready for any challenge they send your way.\n\nYou would be wise to consider obtaining yet another of the weapons of old to aid in our conflict.\n\nLet me know how you'd like to proceed.", completion = "A sound choice.", objectives = "Choose a third artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44432] = { id = 44432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Chosen" }
