quests[44442] = { id = 44442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: New Blood 5" }
quests[44443] = { id = 44443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of the Ancients", description = "You've proven yourself to be a druid without equal, but if we are to succeed in our battles against the Burning Legion you need you to take advantage of every opportunity to stay ahead of our foes.\n\nYou should consider obtaining one final weapon of the Ancients. Its powers will maximize your ability to adapt to whatever the Legion can throw our way.\n\nLet me know how you'd like to proceed.", completion = "A sound choice.", objectives = "Choose a fourth artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
