quests[44447] = { id = 44447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resto Chosen" }
quests[44448] = { id = 44448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the House of Light and Shadow", description = "The Tears of Elune are ready for you, {name}. I am uncertain what to do from here. Take the relic back to your order hall and try to use it on Light's Heart.\n\nMaybe make them touch? Honestly your guess is as good as mine.\n\nLet's hope this works!", progress = "Any news?", completion = "Dead? The titans are dead?\n\n<Khadgar ponders the news for a minute.>\n\nIt explains so much, yet I cannot help but feel an overwhelming sense of sadness. We have been on our own all along. Our gods killed before we were born.\n\nAs for the Army of the Light and Illidan, I am at a loss. I have never felt so powerless.\n\nIllidan is dead and the Golden Army fights an endless war in our name from across the cosmos.\n\nI need a moment, {name}. This is too much bad news for an old man to bear.", objectives = "Take the Tears of Elune to Light's Heart in your Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44449] = { id = 44449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Quenching", description = "Now that we have a frost mage at our disposal, testing this method out should be a cinch.\n\nHere are the plans for what I'd like you to make. Get to work and give me the armguards when you're finished.", progress = "How's that technique coming along?", completion = "Look at that shine!", objectives = "Craft a pair of Hard Leystone Armguards for Alard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44455] = { id = 44455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Downfall Tracking" }
quests[44457] = { id = 44457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotherly Love", description = "Maiev will be somewhere in the prison. I found her discarded armor on my way here.\n\nI know the two of you have a history. I trust that will not be a problem.\n\nLet's split up to search the cells more quickly. We must find her.", completion = "<Maiev's face is bruised, her lips cracked, and her body covered in scars. She looks thin and ragged, but she moves with purpose.>\n\nFor weeks they tried to break me. Amateurs!\n\nI kept my silence. I counted the minutes, measured their steps, and listened to the voices beyond my cell.\n\nI have been waiting for my chance to escape, and to strike back at my captors.\n\nNow, you bring my armor AND my blade. It's your turn to set me free, {class}. Let us destroy the Legion together.", objectives = "Find Maiev Shadowsong in Black Rook Prison.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44458] = { id = 44458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Blood of Our Enemy 1" }
quests[44459] = { id = 44459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Blood of Our Enemy 2" }
quests[44460] = { id = 44460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Blood of Our Enemy 3" }
quests[44461] = { id = 44461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Blood of Our Enemy 4" }
quests[44462] = { id = 44462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Blood of Our Enemy 5" }
quests[44463] = { id = 44463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Among Them", description = "It is just as we suspected, {name}! The demons thought they could take us by surprise.\n\nQuickly, to arms! Warn the King!", progress = "Now is not a good time.", completion = "I must admit, you saved us from what might have been a terrible tragedy. You have my gratitude, {class}.", objectives = "Protect the King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44464] = { id = 44464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakenings", description = "Light's Heart is to serve as the vessel for Illidan Stormrage's rebirth: my last act of service to the Light.\n\nBut Illidan is dead and his soul is lost in the Nether. Before we may attempt to recover his soul, we must prepare the vessel for his return.\n\nAcross two worlds exist echoes of Illidan's past. You must venture out and find the echoes.\n\nStart where all life begins, {name}: birth. Find Illidan's birthplace in Val'sharah. Awaken the memory.", progress = "When our work is complete, I will be lost to the Great Dark.", completion = "An auspicious start to a life of tragedy. Perhaps one of the few joyous memories Illidan would have in his life. While the years that followed tested the prophesied child, they would never break him. You must remember that, despite what you may see as our journey continues.\n\nThere is much more to be done, but I am not yet ready. I will call for you when it is time.", objectives = "Witness the Awakening of Illidan Stormrage in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44465] = { id = 44465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting Earthcallers", description = "Felinda Frye has recently joined us at the Heart of Azeroth. She oversees the recruitment and training of our Earthcallers.\n\nI recommend that you speak with her at your soonest convenience, Farseer {name}. The Earthcallers are powerful shaman and will greatly bolster our ranks.", completion = "Greetings, Farseer {name}. I have been waiting for you.\n\nThe Earthcallers are ready and at your command!", objectives = "Speak to Felinda Frye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44466] = { id = 44466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unclear Path", description = "Much of Illidan's formative years were spent in Val'sharah, alongside his twin brother, Malfurion.\n\nAs young night elves, the twins vied for the affection of the young priestess, Tyrande, as they underwent the trials of the demi-god, Cenarius.\n\nWe must travel to the Dreamgrove now, where Illidan's true path would be forged.", progress = "You mustn't lose hope.", completion = "Failure. Rejection. From that day, Illidan would be haunted by both. Ever undaunted, he would continue the search for his destiny. Another path would be found.", objectives = "Witness Illidan's Resilience at the Dreamgrove in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
