quests[44471] = { id = 44471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Sight", description = "Though young King Anduin is a noble soul, he may lack the conviction of his father. The Alliance needs a leader who will do what needs to be done. The Legion will strike at the first hint of weakness.\n\nEven now, I sense something amiss, {name}. I fear that not all is as it seems.\n\nQuickly, use your Spectral Sight. We must know if there are foes among us!", progress = "Time is precious.", completion = "Of course the Legion would try to infiltrate this funeral. Having all the leaders of the Alliance gathered in one place at one time... it is too tasty a target for the demons to resist!", objectives = "Use your Spectral Sight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
